def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    fruit_salad_patches = image_patch.find("fruit salad")
    rose_container_patches = image_patch.find("rose container")

    if not fruit_salad_patches or not rose_container_patches:
        return image_patch

    fruit_salad_depths = [patch.compute_depth() for patch in fruit_salad_patches]
    rose_container_depths = [patch.compute_depth() for patch in rose_container_patches]

    max_fruit_salad_depth = max(fruit_salad_depths)
    min_rose_container_depth = min(rose_container_depths)

    above = [fs for fs in fruit_salad_patches if fs.compute_depth() < min_rose_container_depth]
    below = [rc for rc in rose_container_patches if rc.compute_depth() > max_fruit_salad_depth]

    if above and below:
        return above[0]
    elif above:
        return above[0]
    elif below:
        return below[0]
    else:
        return image_patch

